// Recebe a linha da caixa de fumaça (app16-4) e monta o ponto do InfluxDB.
let p = msg.payload;
if (typeof p === "string") {
    try { p = JSON.parse(p); }
    catch (e) { node.error("Payload não é JSON válido", msg); return null; }
}

// coleta = o dia, no horário de Brasília. Uma sessão por dia, como pede o protocolo.
const coleta = new Date().toLocaleDateString("sv-SE", { timeZone: "America/Sao_Paulo" });

const NOMES = ["ar", "alcool", "vapor", "fumaca", "chama"];
const CAMPOS = ["amostra", "rodada", "temp", "umid", "tvoc", "eco2", "raw_h2", "raw_ethanol",
                "pressao", "pm1_0", "pm2_5", "nc0_5", "nc1_0", "nc2_5", "pm10", "estimulo"];

// Todo campo vira número decimal: o InfluxDB recusa o mesmo campo ora inteiro, ora decimal.
const fields = {};
for (const c of CAMPOS) {
    const v = Number(p[c]);
    if (Number.isFinite(v)) fields[c] = v;
}
if (fields.estimulo === undefined) { node.warn("Linha sem estímulo: descartada"); return null; }

// coleta e device viram tags: é por elas que o notebook separa treino e coleta nova.
const tags = { coleta: coleta, device: p.device || "caixa-fumaca" };

node.status({ fill: "green", shape: "dot",
    text: coleta + " | " + (NOMES[fields.estimulo] || "?") + " | rodada " + fields.rodada });

// node-red-contrib-influxdb: payload = [fields, tags]
msg.payload = [fields, tags];
return msg;
